def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row),
             key=lambda x: sum(row.count(x) for row in grid))

    # Find a full row or column of color 2.
    axis = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            axis = ("h", r)
            break
    if axis is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                axis = ("v", c)
                break
    if axis is None:
        return [row[:] for row in grid]

    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    orient, pos = axis

    if orient == "v":
        cols = [c for r, c, _ in cells]
        lo, hi = min(cols), max(cols)
        if hi < pos:
            shift = pos - 1 - hi
            outer = lo + shift - 1
        else:
            shift = pos + 1 - lo
            outer = hi + shift + 1

        for r, c, _ in cells:
            out[r][c] = bg
        moved = [(r, c + shift, color) for r, c, color in cells]
        for r, c, color in moved:
            out[r][c] = color
        if 0 <= outer < w:
            for r in range(h):
                out[r][outer] = 8

    else:
        rows = [r for r, c, _ in cells]
        lo, hi = min(rows), max(rows)
        if hi < pos:
            shift = pos - 1 - hi
            outer = lo + shift - 1
        else:
            shift = pos + 1 - lo
            outer = hi + shift + 1

        for r, c, _ in cells:
            out[r][c] = bg
        moved = [(r + shift, c, color) for r, c, color in cells]
        for r, c, color in moved:
            out[r][c] = color
        if 0 <= outer < h:
            for c in range(w):
                out[outer][c] = 8

    return out
